    for (int i = 0; s[i] != 0; i++) {
        if (s[i] == '\n') { s[i] = 0; break; }
        if (isupper((unsigned char)s[i])) s[i] = (char)tolower((unsigned char)s[i]);
        else if (islower((unsigned char)s[i])) s[i] = (char)toupper((unsigned char)s[i]);
    }
    printf("%s\n", s);
    return 0;
}

