#include <stdio.h>

int main(void) {
    char pan[32];
    if (scanf("%31s", pan) != 1) return 0;
    int n = 0;
    while (pan[n] != 0) n++;
    if (n != 10) { printf("INVALID\n"); return 0; }
    for (int i = 0; i < 5; i++) {
        if (!(pan[i] >= 'A' && pan[i] <= 'Z')) { printf("INVALID\n"); return 0; }
    }
    for (int i = 5; i < 9; i++) {
        if (!(pan[i] >= '0' && pan[i] <= '9')) { printf("INVALID\n"); return 0; }
    }
    if (!(pan[9] >= 'A' && pan[9] <= 'Z')) { printf("INVALID\n"); return 0; }
    printf("VALID\n");
    return 0;
}

#include <stdio.h>

static int cmp_str(const char *a, const char *b) {
    int i = 0;
    while (a[i] != 0 && b[i] != 0) {
        if (a[i] != b[i]) return a[i] - b[i];
        i++;
    }
    return a[i] - b[i];
}

int main(void) {
    char s1[64], s2[64], s3[64];
    if (scanf("%63s %63s %63s", s1, s2, s3) != 3) return 0;
    char *p[3] = {s1, s2, s3};
    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (cmp_str(p[i], p[j]) > 0) {
                char *t = p[i];
                p[i] = p[j];
                p[j] = t;
            }
        }
    }
    printf("%s\n%s\n%s\n", p[0], p[1], p[2]);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void) {
    char s[128];
    if (scanf("%127s", s) != 1) return 0;
    for (int i = 0; s[i] != 0; i++) {
        if (isupper((unsigned char)s[i])) {
            putchar('_');
            putchar(tolower((unsigned char)s[i]));
        } else {
            putchar(s[i]);
        }
    }
    putchar('\n');
    return 0;
}
